<script setup>
import {ref,nextTick} from 'vue';import {useInvestigation} from './useInvestigation';
const {state,ask,select}=useInvestigation();const input=ref(''),body=ref(null);
async function send(q=input.value){if(!q.trim())return;ask(q);input.value='';await nextTick();body.value?.scrollTo({top:body.value.scrollHeight,behavior:'smooth'})}
</script><template><div class="chat-content"><div class="conversation-messages" ref="body" aria-live="polite"><div v-if="!state.messages.length" class="chat-intro"><span class="eyeline">TRACE ASSISTANT</span><h3>מה תרצו להבין?</h3><p>כל מסקנה מתחילה בראיה שאפשר לבדוק.</p><button class="suggestion" @click="send('למה לא הייתה תגובה במשך 102 שניות?')">למה לא הייתה תגובה במשך 102 שניות? ↖</button><button class="suggestion" @click="send('מה המפעיל ראה ועשה?')">מה המפעיל ראה ועשה? ↖</button></div><article v-for="(m,i) in state.messages" :key="i" :class="['chat-message',m.role]"><span class="eyeline">{{m.role==='user'?'השאלה שלכם':'TRACE · תשובת הדגמה'}}</span><p>{{m.text}}</p><div class="citation-list"><button v-for="id in m.refs" :key="id" @click="select(id)">{{id}} ↖</button></div><button v-if="m.refs?.length" class="approve-link" @click="state.approved=true">{{state.approved?'✓ המסקנה אושרה במפגש הזה':'אישור מסקנה +'}}</button></article></div><form class="chat-form" @submit.prevent="send()"><input v-model="input" aria-label="שאלה לתחקיר" placeholder="שאלה על האירוע…" /><button :disabled="!input.trim()" aria-label="שליחת שאלה">↑</button></form><small class="simulation-note">תשובות מוכנות להמחשה</small></div></template>